package at.hausgarten.service;

import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;

/** Immutable private browser-media blobs. Uploads stream to an epoch-scoped temporary directory. */
final class BrowserMediaFiles {
    static final int CHUNK_BYTES=65536;
    interface Budget {void require(long additionalBytes)throws IOException;}
    private final File media,uploads;private final Budget budget;private final Map<String,String> verifiedReads=new HashMap<>();
    BrowserMediaFiles(File media,File uploads){this(media,uploads,bytes->{File parent=uploads;while(!parent.exists()&&parent.getParentFile()!=null)parent=parent.getParentFile();if(parent.getUsableSpace()<bytes+8L*1024*1024)throw failure("SPACE_REQUIRED");});}
    BrowserMediaFiles(File media,File uploads,Budget budget){this.media=media;this.uploads=uploads;this.budget=budget;}
    private static IOException failure(String code){return new IOException("BROWSER_MEDIA_"+code);}
    private static void directory(File directory)throws IOException {if(Files.isSymbolicLink(directory.toPath()))throw failure("PATH_INVALID");if(!directory.isDirectory()&&!directory.mkdirs())throw failure("STORAGE_UNAVAILABLE");}
    private File upload(String id,String suffix)throws IOException {if(id==null||!id.matches("[0-9a-f]{64}"))throw failure("UPLOAD_INVALID");directory(uploads);File file=new File(uploads,id+suffix);if(Files.isSymbolicLink(file.toPath()))throw failure("PATH_INVALID");return file;}
    private static void mime(String value)throws IOException {if(value==null||value.length()>200||!value.matches("[A-Za-z0-9!#$&^_.+*-]+/[A-Za-z0-9!#$&^_.+*-]+"))throw failure("MIME_INVALID");}
    synchronized JSONObject begin(String id,long size,String type)throws Exception {
        if(size<0||size>9007199254740991L)throw failure("SIZE_INVALID");mime(type);File state=upload(id,".json");JSONObject record;
        if(state.exists()){record=json(state);if(record.optInt("formatVersion")!=1||record.getLong("byte_size")!=size||!record.getString("mime_type").equals(type))throw failure("REPLAY_MISMATCH");}
        else{if(upload(id,".part").exists())throw failure("UPLOAD_REVIEW_REQUIRED");record=new JSONObject().put("formatVersion",1).put("byte_size",size).put("mime_type",type).put("phase","UPLOADING");atomic(state,record);}
        if(record.optString("phase").equals("COMPLETE")){verifyReference(media,record.getJSONObject("reference"));return new JSONObject().put("upload_id",id).put("next_offset",0).put("complete",true).put("reference",record.getJSONObject("reference"));}
        File part=upload(id,".part");long offset=part.exists()?part.length():0;if(offset>size)throw failure("UPLOAD_REVIEW_REQUIRED");return new JSONObject().put("upload_id",id).put("next_offset",offset).put("complete",false);
    }
    synchronized JSONObject append(String id,long offset,byte[] chunk)throws Exception {
        if(chunk==null||chunk.length<1||chunk.length>CHUNK_BYTES||offset<0)throw failure("CHUNK_INVALID");JSONObject record=json(upload(id,".json"));long size=record.getLong("byte_size"),end;try{end=Math.addExact(offset,chunk.length);}catch(ArithmeticException invalid){throw failure("CHUNK_INVALID");}if(end>size)throw failure("CHUNK_INVALID");
        if(record.optString("phase").equals("COMPLETE")){JSONObject ref=record.getJSONObject("reference");verifyReference(media,ref);byte[] previous=read(ref,offset,chunk.length);if(!java.util.Arrays.equals(previous,chunk))throw failure("REPLAY_MISMATCH");return new JSONObject().put("next_offset",end);}if(!record.optString("phase").equals("UPLOADING"))throw failure("UPLOAD_CLOSED");File part=upload(id,".part");long previous=part.exists()?part.length():0;if(offset>previous)throw failure("CHUNK_ORDER_INVALID");int retained=(int)Math.min(chunk.length,previous-offset);
        try(RandomAccessFile file=new RandomAccessFile(part,"rw")){file.seek(offset);for(int i=0;i<retained;i++)if(file.read()!=(chunk[i]&255))throw failure("REPLAY_MISMATCH");if(end>previous){budget.require(end-previous);file.seek(previous);file.write(chunk,retained,chunk.length-retained);file.getFD().sync();}}
        return new JSONObject().put("next_offset",Math.max(previous,end));
    }
    synchronized JSONObject complete(String id)throws Exception {
        File state=upload(id,".json");JSONObject record=json(state);if(record.optString("phase").equals("COMPLETE")){JSONObject ref=record.getJSONObject("reference");verifyReference(media,ref);return ref;}
        if(!Arrays.asList("UPLOADING","COMMITTING").contains(record.optString("phase")))throw failure("UPLOAD_REVIEW_REQUIRED");File part=upload(id,".part");long size=record.getLong("byte_size");String sha=record.optString("sha256");
        if(sha.isEmpty()){if(!part.exists()&&size==0){budget.require(0);try(FileOutputStream output=new FileOutputStream(part)){output.getFD().sync();}}if(!part.isFile()||part.length()!=size)throw failure("UPLOAD_INCOMPLETE");sha=hash(part);record.put("phase","COMMITTING").put("sha256",sha);atomic(state,record);}
        if(!sha.matches("[0-9a-f]{64}"))throw failure("UPLOAD_REVIEW_REQUIRED");directory(media);File target=new File(media,sha+".blob");if(Files.isSymbolicLink(target.toPath()))throw failure("PATH_INVALID");JSONObject ref=new JSONObject().put("__hg_media_ref",1).put("sha256",sha).put("byte_size",size).put("mime_type",record.getString("mime_type")).put("representation","blob");
        if(target.exists())verifyReference(media,ref);else{if(!part.isFile()||part.length()!=size||!hash(part).equals(sha))throw failure("UPLOAD_INCOMPLETE");Files.move(part.toPath(),target.toPath(),StandardCopyOption.ATOMIC_MOVE);}
        verifyReference(media,ref);record.put("phase","COMPLETE").put("reference",ref);atomic(state,record);if(part.isFile()&&part.length()==size&&hash(part).equals(sha))try{Files.delete(part.toPath());}catch(IOException retained){/* Only an owned verified duplicate temp; retaining it is harmless. */}return ref;
    }
    synchronized byte[] read(JSONObject ref,long offset,int length)throws Exception {validateReference(ref);if(offset<0||length<1||length>CHUNK_BYTES||offset>ref.getLong("byte_size"))throw failure("CHUNK_INVALID");File file=referenceFile(media,ref);String before=stamp(file),sha=ref.getString("sha256");if(!before.equals(verifiedReads.get(sha))){verifyReference(media,ref);if(!before.equals(stamp(file)))throw failure("ORIGINAL_MISSING_OR_CHANGED");if(verifiedReads.size()>256)verifiedReads.clear();verifiedReads.put(sha,before);}if(file.length()!=ref.getLong("byte_size"))throw failure("ORIGINAL_MISSING_OR_CHANGED");int count=(int)Math.min(length,file.length()-offset);byte[] data=new byte[count];try(RandomAccessFile input=new RandomAccessFile(file,"r")){input.seek(offset);input.readFully(data);}if(!before.equals(stamp(file)))throw failure("ORIGINAL_MISSING_OR_CHANGED");return data;}
    private static String stamp(File file)throws IOException {java.nio.file.attribute.BasicFileAttributes attrs=Files.readAttributes(file.toPath(),java.nio.file.attribute.BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);if(!attrs.isRegularFile())throw failure("ORIGINAL_MISSING");return attrs.size()+":"+attrs.lastModifiedTime()+":"+String.valueOf(attrs.fileKey());}
    static File referenceFile(File directory,JSONObject ref)throws Exception {validateReference(ref);if(Files.isSymbolicLink(directory.toPath()))throw failure("PATH_INVALID");File file=new File(directory,ref.getString("sha256")+".blob");if(Files.isSymbolicLink(file.toPath())||!file.getCanonicalFile().getParentFile().equals(directory.getCanonicalFile()))throw failure("PATH_INVALID");return file;}
    static void verifyReference(File directory,JSONObject ref)throws Exception {File file=referenceFile(directory,ref);if(!file.isFile()||file.length()!=ref.getLong("byte_size")||!hash(file).equals(ref.getString("sha256")))throw failure("ORIGINAL_MISSING_OR_CHANGED");}
    static void validateReference(JSONObject ref)throws Exception {
        if(!"1".equals(String.valueOf(ref.opt("__hg_media_ref")))||!ref.optString("sha256").matches("[0-9a-f]{64}"))throw failure("REFERENCE_INVALID");long size;try{size=new java.math.BigDecimal(ref.get("byte_size").toString()).longValueExact();}catch(Exception invalid){throw failure("REFERENCE_INVALID");}if(size<0||size>9007199254740991L)throw failure("REFERENCE_INVALID");mime(ref.optString("mime_type"));String representation=ref.optString("representation");if(!Arrays.asList("blob","data_url").contains(representation))throw failure("REFERENCE_INVALID");if(representation.equals("data_url")&&!ref.optString("data_url_prefix").matches("data:[A-Za-z0-9!#$&^_.+*/=-]{1,240};base64,"))throw failure("REFERENCE_INVALID");for(Iterator<String> fields=ref.keys();fields.hasNext();)if(!Arrays.asList("__hg_media_ref","sha256","byte_size","mime_type","representation","data_url_prefix").contains(fields.next()))throw failure("REFERENCE_INVALID");
    }
    static JSONArray references(JSONObject graph)throws Exception {JSONArray found=new JSONArray();walk(graph,found,0);return found;}
    private static void walk(Object value,JSONArray found,int depth)throws Exception {if(depth>40)throw failure("GRAPH_INVALID");if(value instanceof JSONObject){JSONObject object=(JSONObject)value;if(object.has("__hg_media_ref")){validateReference(object);found.put(new JSONObject(object.toString()));return;}for(Iterator<String> fields=object.keys();fields.hasNext();){String field=fields.next();if(field.matches("(?i).*(password|passwd|secret|credential|oauth|recovery.?code|api.?key|authorization|token).*")||field.equalsIgnoreCase("token"))throw failure("GRAPH_SECRET_FIELD");walk(object.get(field),found,depth+1);}}else if(value instanceof JSONArray){JSONArray array=(JSONArray)value;for(int i=0;i<array.length();i++)walk(array.get(i),found,depth+1);}else if(value instanceof String&&((String)value).matches("(?s)^data:[^,]{1,256};base64,.*"))throw failure("INLINE_MEDIA_FORBIDDEN");}
    static void purgeUnreferenced(File directory,Set<String> keep)throws IOException {
        if(directory==null||!directory.exists())return;if(Files.isSymbolicLink(directory.toPath())||!directory.isDirectory())throw failure("PATH_INVALID");File[] files=directory.listFiles();if(files==null)throw failure("STORAGE_UNAVAILABLE");for(File file:files){String name=file.getName();if(!name.matches("[0-9a-f]{64}\\.blob"))throw failure("PATH_INVALID");if(!keep.contains(name.substring(0,64))){if(Files.isSymbolicLink(file.toPath())||!file.isFile())throw failure("PATH_INVALID");Files.deleteIfExists(file.toPath());}}
    }
    private static JSONObject json(File file)throws Exception {if(!file.isFile()||file.length()>65536)throw failure("UPLOAD_INVALID");JSONObject record=new JSONObject(new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));if(!"1".equals(String.valueOf(record.opt("formatVersion"))))throw failure("UPLOAD_INVALID");return record;}
    private static void atomic(File file,JSONObject record)throws Exception {directory(file.getParentFile());File part=new File(file.getParentFile(),file.getName()+".new-"+UUID.randomUUID());try{try(FileOutputStream output=new FileOutputStream(part)){output.write(record.toString().getBytes(StandardCharsets.UTF_8));output.getFD().sync();}Files.move(part.toPath(),file.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(part.toPath());}}
    static String hash(File file)throws Exception {MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream input=new BufferedInputStream(new FileInputStream(file))){byte[] block=new byte[CHUNK_BYTES];int count;while((count=input.read(block))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("BROWSER_MEDIA_INTERRUPTED");digest.update(block,0,count);}}StringBuilder value=new StringBuilder();for(byte b:digest.digest())value.append(String.format(Locale.ROOT,"%02x",b&255));return value.toString();}
}
